CREATE TABLE IF NOT EXISTS tb_notice_outbox(product_id BIGINT PRIMARY KEY,payload TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error VARCHAR(80) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_notice_pending(status,next_at));
CREATE TABLE IF NOT EXISTS tb_notice_consumed(product_id BIGINT PRIMARY KEY,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tb_admin_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NOT NULL,kind VARCHAR(32) NOT NULL,target_id BIGINT NOT NULL,action VARCHAR(32) NOT NULL,note VARCHAR(1000) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tb_ai_feedback(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,draft_id BIGINT NOT NULL,job_id VARCHAR(64) NOT NULL,rating VARCHAR(16) NOT NULL,reason VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_ai_feedback(user_id,job_id));
CREATE TABLE IF NOT EXISTS tb_notice_preference(user_id BIGINT PRIMARY KEY,price_enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tb_product_alert(user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,last_price DECIMAL(10,2) NULL,last_status INT NULL,PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS tb_ai_field_edit(draft_id BIGINT NOT NULL,field_name VARCHAR(32) NOT NULL,edits INT NOT NULL DEFAULT 1,PRIMARY KEY(draft_id,field_name));
CREATE TABLE IF NOT EXISTS tb_account_restriction(user_id BIGINT PRIMARY KEY,reason VARCHAR(1000) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
